with valid as (select id, product_id, quantity, unit_price, quantity + unit_price as line_total, quantity + unit_price as line_total_2 from order_items where product_id is not null) select d.category, count(*) as num_rows, round(sum(e.line_total_2), 2) as total_line_total_2, avg(e.unit_price) as avg_unit_price from valid e inner join products d on e.product_id = d.id group by d.category;
